@login_required
def cash_report(request):
    """Cash flow report"""
    
    from_date = request.GET.get('from_date', (date.today() - timedelta(days=30)).strftime('%Y-%m-%d'))
    to_date = request.GET.get('to_date', date.today().strftime('%Y-%m-%d'))
    
    from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
    to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
    
    # Get transactions
    transactions = CashTransaction.objects.filter(
        date__date__gte=from_date_obj,
        date__date__lte=to_date_obj
    ).order_by('date')
    
    # Calculate totals by type
    inflow_by_type = {}
    outflow_by_type = {}
    
    for trans in transactions:
        if trans.is_inflow:
            inflow_by_type[trans.transaction_type] = inflow_by_type.get(trans.transaction_type, Decimal('0.0')) + trans.amount
        else:
            outflow_by_type[trans.transaction_type] = outflow_by_type.get(trans.transaction_type, Decimal('0.0')) + trans.amount
    
    total_inflow = sum(inflow_by_type.values())
    total_outflow = sum(outflow_by_type.values())
    net_cash = total_inflow - total_outflow
    
    # Daily breakdown
    daily_data = []
    current = from_date_obj
    while current <= to_date_obj:
        day_transactions = transactions.filter(date__date=current)
        day_inflow = sum(t.amount for t in day_transactions if t.is_inflow)
        day_outflow = sum(t.amount for t in day_transactions if t.is_outflow)
        daily_data.append({
            'date': current.strftime('%d-%b'),
            'inflow': day_inflow,
            'outflow': day_outflow,
            'net': day_inflow - day_outflow
        })
        current += timedelta(days=1)
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'from_date': from_date,
        'to_date': to_date,
        'inflow_by_type': inflow_by_type,
        'outflow_by_type': outflow_by_type,
        'total_inflow': total_inflow,
        'total_outflow': total_outflow,
        'net_cash': net_cash,
        'daily_data': daily_data,
    }
    return render(request, 'cash/report.html', context)

@login_required
def purchase_create(request):
    if request.method == 'POST':
        try:
            with transaction.atomic():
                vendor_id = request.POST.get('vendor')
                warehouse_id = request.POST.get('warehouse')
                bill_no = request.POST.get('bill_no', '')
                paid = Decimal(request.POST.get('paid', 0))
                
                # ✅ NEW: Cash payment fields
                payment_type = request.POST.get('payment_type', 'credit')
                cash_used = Decimal(request.POST.get('cash_used', 0))
                
                # ✅ FIX: Purchase date field - YEH IMPORTANT HAI
                pur_date = request.POST.get('pur_date')
                if pur_date:
                    pur_date_obj = datetime.strptime(pur_date, '%Y-%m-%d').date()
                else:
                    pur_date_obj = now().date()
                
                if not vendor_id:
                    messages.error(request, 'Please select a vendor!')
                    return redirect('purchase_create')
                if not warehouse_id:
                    messages.error(request, 'Please select a warehouse!')
                    return redirect('purchase_create')
                
                product_ids = request.POST.getlist('product_id[]')
                if not product_ids or not any(product_ids):
                    messages.error(request, 'Please add at least one product!')
                    return redirect('purchase_create')
                
                # ✅ CASH BALANCE VALIDATION - STRICT CHECK
                current_balance = CashBalance.get_balance()
                
                # Agar payment type cash hai ya mixed hai aur cash_used > 0 hai
                if payment_type == 'cash':
                    if cash_used <= 0:
                        messages.error(request, '❌ Cash payment selected but cash amount is 0!')
                        return redirect('purchase_create')
                    if cash_used > current_balance:
                        messages.error(request, f'❌ Insufficient cash balance! Available: Rs. {current_balance:,.2f}, Required: Rs. {cash_used:,.2f}')
                        return redirect('purchase_create')
                    if cash_used > paid:
                        messages.error(request, f'❌ Cash used cannot be more than total paid amount!')
                        return redirect('purchase_create')
                        
                elif payment_type == 'mixed':
                    if cash_used > 0:
                        if cash_used > current_balance:
                            messages.error(request, f'❌ Insufficient cash balance for cash payment! Available: Rs. {current_balance:,.2f}, Required: Rs. {cash_used:,.2f}')
                            return redirect('purchase_create')
                        if cash_used > paid:
                            messages.error(request, f'❌ Cash used cannot be more than total paid amount!')
                            return redirect('purchase_create')
                
                # ✅ FIX: pur_date ko purchase mein set karein
                purchase = Purchase(
                    vendor_id=vendor_id,
                    warehouse_id=warehouse_id,
                    bill_no=bill_no if bill_no else None,
                    paid=paid,
                    payment_type=payment_type,
                    cash_used=cash_used,
                    pur_date=pur_date_obj  # ✅ YEH LINE ADD KAREIN
                )
                purchase.created_by = request.user
                purchase.save()
                
                qtys = request.POST.getlist('qty[]')
                prices = request.POST.getlist('price[]')
                
                for i in range(len(product_ids)):
                    if product_ids[i]:
                        PurchaseItem.objects.create(
                            purchase=purchase,
                            product_id=product_ids[i],
                            qty=float(qtys[i]),
                            price=Decimal(prices[i])
                        )
                
                # ✅ Agar cash use hui hai toh cash balance deduct karo
                if cash_used > 0:
                    CashBalance.update_balance(
                        amount=cash_used,
                        transaction_type='purchase',
                        user=request.user,
                        description=f"Purchase #{purchase.bill_no or purchase.id} - {purchase.vendor.name}"
                    )
                    messages.info(request, f'💰 Rs. {cash_used:,.2f} deducted from cash balance!')
                
                messages.success(request, f'✅ Purchase #{purchase.bill_no or purchase.id} created! Date: {pur_date_obj.strftime("%d-%m-%Y")}')
                return redirect('purchase_list')
                
        except Exception as e:
            messages.error(request, f'❌ Error: {str(e)}')
            return redirect('purchase_create')
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'vendors': Vendor.objects.all().order_by('vendor_code'),
        'warehouses': Warehouse.objects.all(),
        'products': Product.objects.all().order_by('name')[:50],
        'cash_balance': CashBalance.get_balance(),
        'today': date.today(),  # ✅ TODAY CONTEXT FOR TEMPLATE
    }
    return render(request, 'purchases/create.html', context)


