@login_required
def export_report_excel(request, report_name):
    """Export any report to Excel"""
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = report_name.replace('_', ' ').title()
    
    if report_name == 'sales_summary':
        from_date = request.GET.get('from_date', (date.today() - timedelta(days=30)).strftime('%Y-%m-%d'))
        to_date = request.GET.get('to_date', date.today().strftime('%Y-%m-%d'))
        
        sales = Sale.objects.filter(sale_date__date__gte=from_date, sale_date__date__lte=to_date)
        
        headers = ['Bill No', 'Date', 'Customer', 'Amount', 'Discount', 'Paid', 'Outstanding', 'Profit']
        ws.append(headers)
        
        for sale in sales:
            ws.append([
                sale.bill_no,
                sale.sale_date.strftime('%d-%m-%Y'),
                sale.customer.name,
                float(sale.total_amount()),
                float(sale.discount_value),
                float(sale.paid),
                float(sale.outstanding_balance()),
                float(sale.total_profit())
            ])
    
    elif report_name == 'customer_outstanding':
        headers = ['Customer Code', 'Customer Name', 'Phone', 'Outstanding']
        ws.append(headers)
        
        for customer in Customer.objects.all():
            balance = customer.adjusted_outstanding_balance()
            if balance > 0:
                ws.append([
                    customer.customer_code or '-',
                    customer.name,
                    customer.contact_number or '-',
                    float(balance)
                ])
    
    elif report_name == 'low_stock':
        headers = ['Product', 'Current Stock', 'Threshold', 'Status']
        ws.append(headers)
        
        low_stock = Inventory.objects.filter(stock__lt=F('product__low_stock_threshold'))
        for item in low_stock:
            ws.append([
                item.product.name,
                item.stock,
                item.product.low_stock_threshold,
                'LOW STOCK!'
            ])
    
    elif report_name == 'top_products':
        from_date = request.GET.get('from_date', (date.today() - timedelta(days=90)).strftime('%Y-%m-%d'))
        to_date = request.GET.get('to_date', date.today().strftime('%Y-%m-%d'))
        
        top = SaleItem.objects.filter(
            sale__sale_date__date__gte=from_date,
            sale__sale_date__date__lte=to_date
        ).values('product__name').annotate(
            total_qty=Sum('qty'),
            total_sales=Sum('total_amt')
        ).order_by('-total_sales')[:50]
        
        headers = ['Product', 'Quantity Sold', 'Total Sales']
        ws.append(headers)
        
        for item in top:
            ws.append([
                item['product__name'],
                float(item['total_qty']),
                float(item['total_sales'])
            ])
    
    elif report_name == 'customer_wise':
        from_date = request.GET.get('from_date', (date.today() - timedelta(days=30)).strftime('%Y-%m-%d'))
        to_date = request.GET.get('to_date', date.today().strftime('%Y-%m-%d'))
        
        customers = Customer.objects.all()
        headers = ['Customer Code', 'Customer Name', 'Group', 'Total Sales', 'Total Profit', 'Sale Count', 'Outstanding']
        ws.append(headers)
        
        for customer in customers:
            sales = Sale.objects.filter(
                customer=customer,
                sale_date__date__gte=from_date,
                sale_date__date__lte=to_date
            )
            total_sales = sum(s.total_amount() for s in sales)
            if total_sales > 0:
                ws.append([
                    customer.customer_code or '-',
                    customer.name,
                    customer.group.name if customer.group else '-',
                    float(total_sales),
                    float(sum(s.total_profit() for s in sales)),
                    sales.count(),
                    float(customer.adjusted_outstanding_balance())
                ])
    
    # Style headers
    header_fill = PatternFill(start_color="1a1a2e", end_color="1a1a2e", fill_type="solid")
    header_font = Font(bold=True, color="FFFFFF")
    
    for col in range(1, len(headers) + 1):
        cell = ws.cell(row=1, column=col)
        cell.fill = header_fill
        cell.font = header_font
        cell.alignment = Alignment(horizontal="center")
    
    for col in ws.columns:
        max_length = 0
        col_letter = col[0].column_letter
        for cell in col:
            try:
                if len(str(cell.value)) > max_length:
                    max_length = len(str(cell.value))
            except:
                pass
        adjusted_width = min(max_length + 2, 40)
        ws.column_dimensions[col_letter].width = adjusted_width
    
    response = HttpResponse(content_type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    response['Content-Disposition'] = f'attachment; filename="{report_name}_{date.today()}.xlsx"'
    wb.save(response)
    return response

@login_required
def production_order_list(request):
    """List all production orders"""
    orders = ProductionOrder.objects.select_related('product', 'source_warehouse', 'target_warehouse').order_by('-created_at')
    
    status = request.GET.get('status', '')
    if status:
        orders = orders.filter(status=status)
    
    search = request.GET.get('search', '')
    if search:
        orders = orders.filter(order_no__icontains=search) | orders.filter(product__name__icontains=search)
    
    # Statistics
    total_orders = orders.count()
    pending_orders = orders.filter(status__in=['draft', 'planned', 'approved']).count()
    in_progress = orders.filter(status='in_progress').count()
    completed = orders.filter(status='completed').count()
    total_quantity = sum(o.quantity for o in orders)
    
    paginator = Paginator(orders, 25)
    page = request.GET.get('page', 1)
    page_obj = paginator.get_page(page)
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'page_obj': page_obj,
        'status': status,
        'search': search,
        'total_orders': total_orders,
        'pending_orders': pending_orders,
        'in_progress': in_progress,
        'completed': completed,
        'total_quantity': total_quantity,
    }
    return render(request, 'production/order_list.html', context)

@login_required
def print_salary_slip_html(request, pk):
    """Generate and print salary slip for employee as HTML - BASIC SALARY ONLY"""
    employee = get_object_or_404(Employee, pk=pk)
    company = CompanyInfo.objects.first()
    
    # Current month
    current_month = date.today().replace(day=1)
    WORKING_DAYS = 26
    
    # Get attendance for current month
    first_day = current_month
    if current_month.month == 12:
        last_day = date(current_month.year + 1, 1, 1) - timedelta(days=1)
    else:
        last_day = date(current_month.year, current_month.month + 1, 1) - timedelta(days=1)
    
    attendances = Attendance.objects.filter(
        employee=employee,
        date__gte=first_day,
        date__lte=last_day
    )
    
    present_days = attendances.filter(status='present').count()
    absent_days = attendances.filter(status='absent').count()
    
    # Get payroll if exists (for bonus/deductions)
    payroll = Payroll.objects.filter(employee=employee, month=current_month).first()
    
    # Basic Salary ONLY - No allowances
    basic_salary = employee.basic_salary
    total_salary = basic_salary
    
    # Calculations
    per_day = total_salary / WORKING_DAYS if WORKING_DAYS > 0 else 0
    salary_for_present = per_day * present_days
    absence_deduction = per_day * absent_days
    
    # Bonus and deductions from payroll
    bonus = payroll.bonus if payroll else Decimal('0.00')
    tax_deduction = payroll.tax_deduction if payroll else Decimal('0.00')
    loan_deduction = payroll.loan_deduction if payroll else Decimal('0.00')
    other_deduction = payroll.other_deduction if payroll else Decimal('0.00')
    
    total_other_deductions = tax_deduction + loan_deduction + other_deduction
    total_earnings = salary_for_present + bonus
    total_deductions = absence_deduction + total_other_deductions
    net_salary = total_earnings - total_deductions
    
    context = {
        'company_name': company.name if company else 'ERP System',
        'company_address': company.address if company else '',
        'company_phone': company.contact_number if company else '',
        'employee': employee,
        'month': current_month.strftime('%B %Y'),
        'basic_salary': basic_salary,
        'total_salary': total_salary,
        'working_days': WORKING_DAYS,
        'present_days': present_days,
        'absent_days': absent_days,
        'per_day': per_day,
        'salary_for_present': salary_for_present,
        'bonus': bonus,
        'total_earnings': total_earnings,
        'absence_deduction': absence_deduction,
        'tax_deduction': tax_deduction,
        'total_deductions': total_deductions,
        'net_salary': net_salary,
        'current_date': datetime.now().strftime('%d-%m-%Y %H:%M:%S'),
    }
    return render(request, 'hr/salary_slip_print.html', context)

@login_required
def production_order_create(request):
    """Create new production order"""
    if request.method == 'POST':
        try:
            product_id = request.POST.get('product')
            quantity = Decimal(request.POST.get('quantity'))
            planned_start_date = request.POST.get('planned_start_date')
            planned_end_date = request.POST.get('planned_end_date')
            source_warehouse_id = request.POST.get('source_warehouse')
            target_warehouse_id = request.POST.get('target_warehouse')
            notes = request.POST.get('notes', '')
            
            product = get_object_or_404(Product, pk=product_id)
            
            # Check if product has BOM template
            # (You can create a ProductBOMTemplate model for reusability)
            
            order = ProductionOrder.objects.create(
                product=product,
                quantity=quantity,
                planned_start_date=planned_start_date,
                planned_end_date=planned_end_date,
                source_warehouse_id=source_warehouse_id,
                target_warehouse_id=target_warehouse_id,
                notes=notes,
                created_by=request.user,
                status='draft'
            )
            
            messages.success(request, f'✅ Production Order #{order.order_no} created!')
            return redirect('production_order_detail', pk=order.pk)
            
        except Exception as e:
            messages.error(request, f'❌ Error: {str(e)}')
            return redirect('production_order_create')
    
    warehouses = Warehouse.objects.all()
    products = Product.objects.all()
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'warehouses': warehouses,
        'products': products,
    }
    return render(request, 'production/order_create.html', context)


