@login_required
def payroll_add(request, pk):
    """Add payroll for an employee"""
    if not request.user.groups.filter(name__in=['HR Manager', 'Accountant', 'Owner']).exists():
        messages.error(request, 'Access denied!')
        return redirect('dashboard')
    
    employee = get_object_or_404(Employee, pk=pk)
    
    if request.method == 'POST':
        try:
            month = request.POST.get('month')
            bonus = Decimal(request.POST.get('bonus', 0))
            overtime = Decimal(request.POST.get('overtime', 0))
            tax_deduction = Decimal(request.POST.get('tax_deduction', 0))
            loan_deduction = Decimal(request.POST.get('loan_deduction', 0))
            other_deduction = Decimal(request.POST.get('other_deduction', 0))
            
            # Get attendance stats for the month
            year, month_num = map(int, month.split('-'))
            first_day = date(year, month_num, 1)
            if month_num == 12:
                last_day = date(year + 1, 1, 1) - timedelta(days=1)
            else:
                last_day = date(year, month_num + 1, 1) - timedelta(days=1)
            
            attendances = Attendance.objects.filter(
                employee=employee,
                date__gte=first_day,
                date__lte=last_day
            )
            
            total_present = attendances.filter(status='present').count()
            total_absent = attendances.filter(status='absent').count()
            total_late = attendances.filter(status='late').count()
            total_halfday = attendances.filter(status='halfday').count()
            
            # Calculate absence deduction (1 day salary = basic_salary/working_days)
            working_days = 26  # Approximate working days in a month
            per_day_salary = employee.basic_salary / working_days
            absence_deduction = per_day_salary * total_absent
            
            payroll = Payroll.objects.create(
                employee=employee,
                month=first_day,
                basic_salary=employee.basic_salary,
                house_allowance=employee.house_allowance,
                other_allowance=employee.other_allowance,
                bonus=bonus,
                overtime=overtime,
                tax_deduction=tax_deduction,
                loan_deduction=loan_deduction,
                absence_deduction=absence_deduction,
                other_deduction=other_deduction,
                total_present=total_present,
                total_absent=total_absent,
                total_late=total_late,
                total_halfday=total_halfday,
                status='processed',
                created_by=request.user
            )
            
            messages.success(request, f'✅ Payroll created for {employee.name} - {first_day.strftime("%B %Y")}!')
            return redirect('employee_payroll', pk=employee.pk)
            
        except Exception as e:
            messages.error(request, f'❌ Error: {str(e)}')
            return redirect('payroll_add', pk=pk)
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'employee': employee,
        'current_month': date.today().strftime('%Y-%m'),
    }
    return render(request, 'hr/payroll_add.html', context)


@login_required
def payslip_generate(request, pk):
    """Generate payslip PDF"""
    from reportlab.lib.pagesizes import A4
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
    from reportlab.lib import colors
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.units import inch
    from reportlab.lib.enums import TA_CENTER, TA_RIGHT
    from io import BytesIO
    from django.http import HttpResponse
    
    payroll = get_object_or_404(Payroll, pk=pk)
    employee = payroll.employee
    company = CompanyInfo.objects.first()
    
    buffer = BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, topMargin=0.5*inch, bottomMargin=0.5*inch)
    styles = getSampleStyleSheet()
    story = []
    
    # Title
    title_style = ParagraphStyle('Title', parent=styles['Heading1'], fontSize=18, alignment=TA_CENTER)
    story.append(Paragraph(company.name if company else "ERP SYSTEM", title_style))
    story.append(Paragraph("PAYSLIP", title_style))
    story.append(Paragraph(f"Month: {payroll.month.strftime('%B %Y')}", styles['Normal']))
    story.append(Spacer(1, 0.3*inch))
    
    # Employee Info
    emp_data = [
        ['Employee Name:', employee.name],
        ['Employee ID:', employee.employee_id],
        ['Department:', employee.get_department_display()],
        ['Designation:', employee.designation or '-'],
        ['Joining Date:', employee.joining_date.strftime('%d-%m-%Y')],
    ]
    
    emp_table = Table(emp_data, colWidths=[2*inch, 4*inch])
    emp_table.setStyle(TableStyle([
        ('FONTNAME', (0, 0), (-1, -1), 'Helvetica'),
        ('FONTSIZE', (0, 0), (-1, -1), 9),
        ('VALIGN', (0, 0), (-1, -1), 'TOP'),
        ('TOPPADDING', (0, 0), (-1, -1), 4),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
    ]))
    story.append(emp_table)
    story.append(Spacer(1, 0.3*inch))
    
    # Earnings Table
    earnings_data = [
        ['EARNINGS', 'Amount (Rs.)'],
        ['Basic Salary', f'{payroll.basic_salary:,.2f}'],
        ['House Allowance', f'{payroll.house_allowance:,.2f}'],
        ['Other Allowance', f'{payroll.other_allowance:,.2f}'],
        ['Bonus', f'{payroll.bonus:,.2f}'],
        ['Overtime', f'{payroll.overtime:,.2f}'],
        ['Total Earnings', f'{payroll.total_earnings():,.2f}'],
    ]
    
    earnings_table = Table(earnings_data, colWidths=[3*inch, 2*inch])
    earnings_table.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#1a1d2e')),
        ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('GRID', (0, 0), (-1, -1), 0.5, colors.grey),
        ('ALIGN', (1, 1), (1, -2), 'RIGHT'),
        ('BACKGROUND', (0, -1), (-1, -1), colors.HexColor('#e8ecf4')),
        ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
    ]))
    story.append(earnings_table)
    story.append(Spacer(1, 0.2*inch))
    
    # Deductions Table
    deductions_data = [
        ['DEDUCTIONS', 'Amount (Rs.)'],
        ['Tax Deduction', f'{payroll.tax_deduction:,.2f}'],
        ['Loan Deduction', f'{payroll.loan_deduction:,.2f}'],
        ['Absence Deduction', f'{payroll.absence_deduction:,.2f}'],
        ['Other Deduction', f'{payroll.other_deduction:,.2f}'],
        ['Total Deductions', f'{payroll.total_deductions():,.2f}'],
    ]
    
    deductions_table = Table(deductions_data, colWidths=[3*inch, 2*inch])
    deductions_table.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#1a1d2e')),
        ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('GRID', (0, 0), (-1, -1), 0.5, colors.grey),
        ('ALIGN', (1, 1), (1, -2), 'RIGHT'),
        ('BACKGROUND', (0, -1), (-1, -1), colors.HexColor('#fff3cd')),
        ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
    ]))
    story.append(deductions_table)
    story.append(Spacer(1, 0.3*inch))
    
    # Net Salary
    net_data = [
        ['NET SALARY', f'Rs. {payroll.net_salary():,.2f}'],
    ]
    net_table = Table(net_data, colWidths=[3*inch, 2*inch])
    net_table.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#28a745')),
        ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('FONTSIZE', (0, 0), (-1, 0), 12),
        ('ALIGN', (1, 0), (1, 0), 'RIGHT'),
    ]))
    story.append(net_table)
    story.append(Spacer(1, 0.3*inch))
    
    # Attendance Summary
    story.append(Paragraph("<b>Attendance Summary</b>", styles['Heading2']))
    att_data = [
        ['Present', 'Absent', 'Late', 'Half Day'],
        [str(payroll.total_present), str(payroll.total_absent), str(payroll.total_late), str(payroll.total_halfday)],
    ]
    att_table = Table(att_data, colWidths=[1.25*inch]*4)
    att_table.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#1a1d2e')),
        ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
        ('GRID', (0, 0), (-1, -1), 0.5, colors.grey),
        ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
    ]))
    story.append(att_table)
    
    # Footer
    story.append(Spacer(1, 0.5*inch))
    story.append(Paragraph("This is a computer generated payslip.", styles['Normal']))
    story.append(Paragraph(f"Generated on: {now().strftime('%d-%m-%Y %H:%M')}", styles['Normal']))
    
    doc.build(story)
    buffer.seek(0)
    
    response = HttpResponse(buffer, content_type='application/pdf')
    response['Content-Disposition'] = f'attachment; filename="Payslip_{employee.employee_id}_{payroll.month.strftime("%B_%Y")}.pdf"'
    return response

from django.contrib.auth.models import User, Group
from django.contrib.auth.hashers import make_password
from django.db import transaction

# Role mapping
ROLE_GROUPS = {
    'admin': ['Admin', 'Can view all', 'Can edit all', 'Can delete all'],
    'owner': ['Owner', 'Can view reports', 'Can manage users', 'Full access'],
    'salesman': ['Salesman', 'Can create sales', 'Can view customers'],
    'accountant': ['Accountant', 'Can view reports', 'Can view financials'],
    'manager': ['Store Manager', 'Can manage inventory', 'Can approve orders'],
    'warehouse': ['Warehouse Staff', 'Can manage stock', 'Can receive goods'],
}

ROLE_ICONS = {
    'admin': 'bi-shield-lock',
    'owner': 'bi-building',
    'salesman': 'bi-person-badge',
    'accountant': 'bi-calculator',
    'manager': 'bi-people',
    'warehouse': 'bi-box',
}

@login_required
def user_list(request):
    """List all users with role filters"""
    if not request.user.is_superuser and not request.user.groups.filter(name='Owner').exists():
        messages.error(request, 'Access denied! Only administrators can view users.')
        return redirect('dashboard')
    
    users = User.objects.select_related().all()
    
    # Add role info to each user
    for user in users:
        if user.is_superuser:
            user.role = 'admin'
            user.role_display = 'Administrator'
            user.role_icon = 'bi-shield-lock'
        elif user.groups.filter(name='Owner').exists():
            user.role = 'owner'
            user.role_display = 'Owner'
            user.role_icon = 'bi-building'
        elif user.groups.filter(name='Salesman').exists():
            user.role = 'salesman'
            user.role_display = 'Salesman'
            user.role_icon = 'bi-person-badge'
        elif user.groups.filter(name='Accountant').exists():
            user.role = 'accountant'
            user.role_display = 'Accountant'
            user.role_icon = 'bi-calculator'
        elif user.groups.filter(name='Store Manager').exists():
            user.role = 'manager'
            user.role_display = 'Store Manager'
            user.role_icon = 'bi-people'
        elif user.groups.filter(name='Warehouse Staff').exists():
            user.role = 'warehouse'
            user.role_display = 'Warehouse Staff'
            user.role_icon = 'bi-box'
        else:
            user.role = 'staff'
            user.role_display = 'Staff'
            user.role_icon = 'bi-person'
    
    # Filters
    search = request.GET.get('search', '')
    role_filter = request.GET.get('role', '')
    status_filter = request.GET.get('status', '')
    
    if search:
        users = users.filter(Q(username__icontains=search) | Q(email__icontains=search) | Q(first_name__icontains=search))
    if role_filter == 'admin':
        users = users.filter(is_superuser=True)
    elif role_filter == 'owner':
        users = users.filter(groups__name='Owner')
    elif role_filter == 'salesman':
        users = users.filter(groups__name='Salesman')
    elif role_filter == 'accountant':
        users = users.filter(groups__name='Accountant')
    elif role_filter == 'manager':
        users = users.filter(groups__name='Store Manager')
    elif role_filter == 'warehouse':
        users = users.filter(groups__name='Warehouse Staff')
    if status_filter == 'active':
        users = users.filter(is_active=True)
    elif status_filter == 'inactive':
        users = users.filter(is_active=False)
    
    # Counts by role
    admin_count = User.objects.filter(is_superuser=True).count()
    owner_count = User.objects.filter(groups__name='Owner').count()
    salesman_count = User.objects.filter(groups__name='Salesman').count()
    accountant_count = User.objects.filter(groups__name='Accountant').count()
    manager_count = User.objects.filter(groups__name='Store Manager').count()
    warehouse_count = User.objects.filter(groups__name='Warehouse Staff').count()
    
    paginator = Paginator(users, 25)
    page = request.GET.get('page', 1)
    page_obj = paginator.get_page(page)
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'page_obj': page_obj,
        'search': search,
        'role_filter': role_filter,
        'status_filter': status_filter,
        'admin_count': admin_count,
        'owner_count': owner_count,
        'salesman_count': salesman_count,
        'accountant_count': accountant_count,
        'manager_count': manager_count,
        'warehouse_count': warehouse_count,
    }
    return render(request, 'users/role_list.html', context)


@login_required
def user_create(request):
    """Create new user with role"""
    if not request.user.is_superuser and not request.user.groups.filter(name='Owner').exists():
        messages.error(request, 'Access denied! Only administrators can create users.')
        return redirect('dashboard')
    
    if request.method == 'POST':
        try:
            username = request.POST.get('username')
            password = request.POST.get('password')
            confirm_password = request.POST.get('confirm_password')
            full_name = request.POST.get('full_name', '')
            email = request.POST.get('email', '')
            phone = request.POST.get('phone', '')
            role = request.POST.get('role')
            is_active = request.POST.get('is_active') == 'on'
            
            if password != confirm_password:
                messages.error(request, 'Passwords do not match!')
                return redirect('user_create')
            
            if len(password) < 6:
                messages.error(request, 'Password must be at least 6 characters!')
                return redirect('user_create')
            
            if User.objects.filter(username=username).exists():
                messages.error(request, 'Username already exists!')
                return redirect('user_create')
            
            # Split full name
            name_parts = full_name.split(' ', 1)
            first_name = name_parts[0]
            last_name = name_parts[1] if len(name_parts) > 1 else ''
            
            user = User.objects.create(
                username=username,
                email=email,
                first_name=first_name,
                last_name=last_name,
                is_active=is_active,
                password=make_password(password)
            )
            
            # Add to group based on role
            group_name = {
                'admin': None,
                'owner': 'Owner',
                'salesman': 'Salesman',
                'accountant': 'Accountant',
                'manager': 'Store Manager',
                'warehouse': 'Warehouse Staff'
            }.get(role)
            
            if group_name:
                group, _ = Group.objects.get_or_create(name=group_name)
                user.groups.add(group)
            
            if role == 'admin':
                user.is_superuser = True
                user.is_staff = True
                user.save()
            
            messages.success(request, f'✅ User "{username}" created successfully!')
            return redirect('user_list')
            
        except Exception as e:
            messages.error(request, f'❌ Error: {str(e)}')
            return redirect('user_create')
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
    }
    return render(request, 'users/user_create.html', context)


@login_required
def user_edit(request, pk):
    """Edit user details"""
    if not request.user.is_superuser and not request.user.groups.filter(name='Owner').exists():
        messages.error(request, 'Access denied! Only administrators can edit users.')
        return redirect('dashboard')
    
    user = get_object_or_404(User, pk=pk)
    
    # Determine user role
    if user.is_superuser:
        user_role = 'admin'
    elif user.groups.filter(name='Owner').exists():
        user_role = 'owner'
    elif user.groups.filter(name='Salesman').exists():
        user_role = 'salesman'
    elif user.groups.filter(name='Accountant').exists():
        user_role = 'accountant'
    elif user.groups.filter(name='Store Manager').exists():
        user_role = 'manager'
    elif user.groups.filter(name='Warehouse Staff').exists():
        user_role = 'warehouse'
    else:
        user_role = 'staff'
    
    if request.method == 'POST':
        try:
            username = request.POST.get('username')
            full_name = request.POST.get('full_name', '')
            email = request.POST.get('email', '')
            role = request.POST.get('role')
            is_active = request.POST.get('is_active') == 'on'
            is_staff = request.POST.get('is_staff') == 'on'
            
            if User.objects.filter(username=username).exclude(pk=pk).exists():
                messages.error(request, 'Username already exists!')
                return redirect('user_edit', pk=pk)
            
            # Split full name
            name_parts = full_name.split(' ', 1) if full_name else [user.first_name, user.last_name]
            first_name = name_parts[0] if name_parts else user.first_name
            last_name = name_parts[1] if len(name_parts) > 1 else user.last_name
            
            user.username = username
            user.email = email
            user.first_name = first_name
            user.last_name = last_name
            user.is_active = is_active
            user.is_staff = is_staff
            
            # Update groups
            user.groups.clear()
            group_name = {
                'admin': None,
                'owner': 'Owner',
                'salesman': 'Salesman',
                'accountant': 'Accountant',
                'manager': 'Store Manager',
                'warehouse': 'Warehouse Staff'
            }.get(role)
            
            if group_name:
                group, _ = Group.objects.get_or_create(name=group_name)
                user.groups.add(group)
            
            if role == 'admin':
                user.is_superuser = True
            else:
                user.is_superuser = False
            
            user.save()
            
            messages.success(request, f'✅ User "{username}" updated successfully!')
            return redirect('user_list')
            
        except Exception as e:
            messages.error(request, f'❌ Error: {str(e)}')
            return redirect('user_edit', pk=pk)
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'user': user,
        'user_role': user_role,
    }
    return render(request, 'users/user_edit.html', context)


@login_required
def user_delete(request, pk):
    """Delete user"""
    if not request.user.is_superuser and not request.user.groups.filter(name='Owner').exists():
        messages.error(request, 'Access denied! Only administrators can delete users.')
        return redirect('dashboard')
    
    user = get_object_or_404(User, pk=pk)
    
    if user.pk == request.user.pk:
        messages.error(request, 'You cannot delete your own account!')
        return redirect('user_list')
    
    if request.method == 'POST':
        username = user.username
        user.delete()
        messages.success(request, f'🗑️ User "{username}" deleted successfully!')
        return redirect('user_list')
    
    return redirect('user_list')


@login_required
def user_toggle_status(request, pk):
    """Activate/Deactivate user"""
    if not request.user.is_superuser and not request.user.groups.filter(name='Owner').exists():
        messages.error(request, 'Access denied! Only administrators can change user status.')
        return redirect('dashboard')
    
    user = get_object_or_404(User, pk=pk)
    
    if user.pk == request.user.pk:
        messages.error(request, 'You cannot change your own status!')
        return redirect('user_list')
    
    user.is_active = not user.is_active
    user.save()
    
    status = 'activated' if user.is_active else 'deactivated'
    messages.success(request, f'✅ User "{user.username}" has been {status}!')
    return redirect('user_list')


@login_required
def user_reset_password(request, pk):
    """Reset user password"""
    if not request.user.is_superuser and not request.user.groups.filter(name='Owner').exists():
        messages.error(request, 'Access denied! Only administrators can reset passwords.')
        return redirect('dashboard')
    
    user = get_object_or_404(User, pk=pk)
    
    if request.method == 'POST':
        password = request.POST.get('password')
        confirm_password = request.POST.get('confirm_password')
        
        if password != confirm_password:
            messages.error(request, 'Passwords do not match!')
            return redirect('user_reset_password', pk=pk)
        
        if len(password) < 6:
            messages.error(request, 'Password must be at least 6 characters!')
            return redirect('user_reset_password', pk=pk)
        
        user.password = make_password(password)
        user.save()
        
        messages.success(request, f'✅ Password reset for "{user.username}" successfully!')
        return redirect('user_list')
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'user': user,
    }
    return render(request, 'users/user_reset_password.html', context)

