from django.http import JsonResponse
from django.contrib.auth.decorators import login_required
from django.db.models import Sum
from decimal import Decimal
from .models import Purchase, PurchaseRetrnItem

# views_frontend.py

@login_required
def get_purchase_products(request):
    """
    AJAX: Purchase ke saare products dikhaye, sirf wohi jin ki remaining quantity > 0 hai
    Also shows return history for each product
    """
    purchase_id = request.GET.get('purchase_id')
    
    if not purchase_id:
        return JsonResponse({
            'success': False, 
            'message': 'Purchase ID required'
        })
    
    try:
        purchase = Purchase.objects.get(id=purchase_id)
        products = {}
        total_remaining = 0
        total_returned = 0
        
        # ✅ Saare purchase items par loop
        for item in purchase.purchaseitem_set.all():
            # ✅ Calculate total returned quantity for this product (across all returns)
            returned_qty = PurchaseRetrnItem.objects.filter(
                purchase_return__purchase=purchase,
                product=item.product
            ).aggregate(total=Sum('qty'))['total'] or Decimal('0.00')
            
            # ✅ Remaining quantity calculate karein
            original_qty = Decimal(str(item.qty))
            remaining_qty = original_qty - returned_qty
            
            # ✅ Sirf wohi products show karein jinki remaining quantity > 0
            if remaining_qty > 0:
                products[str(item.product.id)] = {
                    'name': item.product.name,
                    'price': float(item.price),
                    'original_qty': float(original_qty),
                    'returned_qty': float(returned_qty),
                    'remaining_qty': float(remaining_qty),
                    'unit': item.product.unit.name if item.product.unit else '',
                    'product_id': item.product.id,
                    'barcode': item.product.barcode or '',
                    'serial_no': item.product.serial_no or '',
                    'fully_returned': False
                }
                total_remaining += remaining_qty
            else:
                # ✅ Product fully returned - still show in history
                if returned_qty > 0:
                    products[str(item.product.id)] = {
                        'name': item.product.name,
                        'price': float(item.price),
                        'original_qty': float(original_qty),
                        'returned_qty': float(returned_qty),
                        'remaining_qty': 0,
                        'unit': item.product.unit.name if item.product.unit else '',
                        'product_id': item.product.id,
                        'barcode': item.product.barcode or '',
                        'serial_no': item.product.serial_no or '',
                        'fully_returned': True
                    }
            
            total_returned += returned_qty
        
        # ✅ Get all returns for this purchase
        returns = PurchaseRetrn.objects.filter(purchase=purchase)
        return_history = []
        for ret in returns:
            ret_items = []
            for r_item in ret.return_items.all():
                ret_items.append({
                    'product_name': r_item.product.name,
                    'product_id': r_item.product.id,
                    'qty': float(r_item.qty),
                    'amount': float(r_item.total_amt),
                    'price': float(r_item.price)
                })
            return_history.append({
                'id': ret.id,
                'date': ret.purchase_return_date.strftime('%d-%m-%Y %H:%M'),
                'reason': ret.get_return_reason_display(),
                'bill_no': ret.bill_no or 'N/A',
                'items': ret_items,
                'total_amount': float(sum(item['amount'] for item in ret_items)),
                'total_items': len(ret_items)
            })
        
        # ✅ Sort return history by date (newest first)
        return_history.sort(key=lambda x: x['date'], reverse=True)
        
        # ✅ Available products count
        available_count = len([p for p in products.values() if p['remaining_qty'] > 0])
        
        return JsonResponse({
            'success': True,
            'products': products,
            'total_remaining': float(total_remaining),
            'total_returned': float(total_returned),
            'return_history': return_history,
            'purchase_bill_no': purchase.bill_no or 'Pending',
            'purchase_date': purchase.pur_date.strftime('%d-%m-%Y'),
            'vendor_name': purchase.vendor.name,
            'vendor_id': purchase.vendor.id,
            'total_products': len(products),
            'available_products': available_count,
            'fully_returned_products': len(products) - available_count,
            'message': f'{available_count} products available for return'
        })
        
    except Purchase.DoesNotExist:
        return JsonResponse({
            'success': False, 
            'message': 'Purchase not found'
        })
    except Exception as e:
        return JsonResponse({
            'success': False, 
            'message': str(e)
        })


@login_required
def get_sale_products(request):
    """Get products from a sale for return"""
    sale_id = request.GET.get('sale_id')
    
    if not sale_id:
        return JsonResponse({'success': False, 'message': 'Sale ID required'})
    
    try:
        sale = Sale.objects.get(id=sale_id)
        products = {}
        
        for item in sale.saleitem_set.all():
            # Calculate remaining quantity (not already returned)
            returned_qty = SaleRetrnItem.objects.filter(
                sale_return__sale=sale,
                product=item.product
            ).aggregate(total=Sum('qty'))['total'] or 0
            
            remaining_qty = item.qty - returned_qty
            
            if remaining_qty > 0:
                products[item.product.id] = {
                    'name': item.product.name,
                    'price': float(item.price),
                    'remaining_qty': remaining_qty
                }
        
        return JsonResponse({'success': True, 'products': products})
        
    except Sale.DoesNotExist:
        return JsonResponse({'success': False, 'message': 'Sale not found'})

@login_required
def warehouse_list(request):
    """List all warehouses with stats"""
    warehouses = Warehouse.objects.select_related('location').all()
    
    search = request.GET.get('search', '')
    if search:
        warehouses = warehouses.filter(
            Q(name__icontains=search) |
            Q(location__name__icontains=search)
        )
    
    # Calculate stats for each warehouse
    total_stock_value = 0
    total_products = 0
    low_stock_count = 0
    
    for wh in warehouses:
        inventory_items = Inventory.objects.filter(warehouse=wh)
        wh.product_count = inventory_items.count()
        wh.stock_value = sum(inv.stock_value() for inv in inventory_items)
        total_stock_value += wh.stock_value
        total_products += wh.product_count
        low_stock_count += sum(1 for inv in inventory_items if inv.check_low_stock())
    
    paginator = Paginator(warehouses, 25)
    page = request.GET.get('page', 1)
    page_obj = paginator.get_page(page)
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'page_obj': page_obj,
        'search': search,
        'total_warehouses': warehouses.count(),
        'total_products': total_products,
        'total_stock_value': total_stock_value,
        'low_stock_count': low_stock_count,
    }
    return render(request, 'warehouses/list.html', context)


@login_required
def warehouse_create(request):
    """Create new warehouse"""
    if request.method == 'POST':
        name = request.POST.get('name', '').strip()
        location_id = request.POST.get('location') or None
        description = request.POST.get('description', '')
        
        if not name:
            messages.error(request, 'Warehouse name is required!')
            return redirect('warehouse_create')
        
        if Warehouse.objects.filter(name__iexact=name).exists():
            messages.error(request, f'Warehouse "{name}" already exists!')
            return redirect('warehouse_create')
        
        warehouse = Warehouse.objects.create(
            name=name,
            location_id=location_id,
            description=description
        )
        
        messages.success(request, f'✅ Warehouse "{warehouse.name}" created successfully!')
        return redirect('warehouse_list')
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'locations': Location.objects.all(),
    }
    return render(request, 'warehouses/create.html', context)


@login_required
def warehouse_update(request, pk):
    """Update warehouse"""
    warehouse = get_object_or_404(Warehouse, pk=pk)
    
    if request.method == 'POST':
        name = request.POST.get('name', '').strip()
        location_id = request.POST.get('location') or None
        description = request.POST.get('description', '')
        
        if not name:
            messages.error(request, 'Warehouse name is required!')
            return redirect('warehouse_update', pk=pk)
        
        if Warehouse.objects.filter(name__iexact=name).exclude(pk=pk).exists():
            messages.error(request, f'Warehouse "{name}" already exists!')
            return redirect('warehouse_update', pk=pk)
        
        warehouse.name = name
        warehouse.location_id = location_id
        warehouse.description = description
        warehouse.save()
        
        messages.success(request, f'✅ Warehouse "{warehouse.name}" updated successfully!')
        return redirect('warehouse_list')
    
    # Get warehouse stats
    inventory_items = Inventory.objects.filter(warehouse=warehouse)
    product_count = inventory_items.count()
    stock_value = sum(inv.stock_value() for inv in inventory_items)
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'warehouse': warehouse,
        'locations': Location.objects.all(),
        'product_count': product_count,
        'stock_value': stock_value,
    }
    return render(request, 'warehouses/update.html', context)


@login_required
def warehouse_inventory(request, pk):
    """View inventory items in a warehouse"""
    from decimal import Decimal  # ✅ Ensure Decimal is imported
    
    warehouse = get_object_or_404(Warehouse, pk=pk)
    inventory_items = Inventory.objects.filter(warehouse=warehouse).select_related('product', 'product__unit')
    
    total_products = inventory_items.count()
    total_stock_value = sum(inv.stock_value() for inv in inventory_items)
    low_stock_count = sum(1 for inv in inventory_items if inv.check_low_stock())
    
    # Add calculated fields
    for inv in inventory_items:
        inv.stock_value = inv.stock_value()
        
        # ✅ FIX: Decimal division
        if inv.stock > 0:
            inv.avg_price = inv.stock_value / Decimal(str(inv.stock))
        else:
            inv.avg_price = Decimal('0.00')
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'warehouse': warehouse,
        'inventory_items': inventory_items,
        'total_products': total_products,
        'total_stock_value': total_stock_value,
        'low_stock_count': low_stock_count,
    }
    return render(request, 'warehouses/inventory.html', context)

