@login_required
def get_product_by_barcode(request):
    """AJAX: Barcode, Serial Number, ya Product Name se product search - SIRF BATCH SELLING PRICE"""
    barcode = request.GET.get('barcode', '').strip()
    serial = request.GET.get('serial', '').strip()
    
    query = barcode or serial
    
    if not query:
        return JsonResponse({'success': False, 'message': 'No query provided'})
    
    product = None
    
    if barcode:
        try:
            product = Product.objects.get(barcode=barcode)
        except Product.DoesNotExist:
            pass
    
    if not product and serial:
        try:
            product = Product.objects.get(serial_no__iexact=serial)
        except Product.DoesNotExist:
            pass
    
    if not product:
        product = Product.objects.filter(name__icontains=query).first()
    
    if not product:
        return JsonResponse({'success': False, 'message': 'Product not found'})
    
    warehouse_id = request.GET.get('warehouse_id', '')
    price = Decimal('0.0')
    stock = 0
    has_selling_price = False
    message = ''
    
    if warehouse_id:
        batch = StockBatch.objects.filter(
            product=product,
            warehouse_id=warehouse_id,
            remaining_qty__gt=0,
            selling_price__gt=0
        ).order_by('id').first()
        
        if batch:
            price = batch.selling_price
            has_selling_price = True
        else:
            price = Decimal('0.0')
            has_selling_price = False
        
        inventory = Inventory.objects.filter(product=product, warehouse_id=warehouse_id).first()
        stock = inventory.stock if inventory else 0
    else:
        batch = StockBatch.objects.filter(
            product=product,
            remaining_qty__gt=0,
            selling_price__gt=0
        ).first()
        
        if batch:
            price = batch.selling_price
            has_selling_price = True
        else:
            price = Decimal('0.0')
            has_selling_price = False
        
        stock = sum(inv.stock for inv in Inventory.objects.filter(product=product))
    
    return JsonResponse({
        'success': True,
        'product': {
            'id': product.id,
            'name': product.name,
            'barcode': product.barcode or '',
            'serial_no': product.serial_no or '',
            'price': str(price),
            'stock': stock,
            'unit': product.unit.name if product.unit else '',
            'has_selling_price': has_selling_price,
            'message': message,
        }
    })


@login_required
def get_customer_balance(request):
    """AJAX: Customer ka balance"""
    customer_id = request.GET.get('customer_id')
    if not customer_id:
        return JsonResponse({'success': False})
    
    try:
        customer = Customer.objects.get(pk=customer_id)
        return JsonResponse({
            'success': True,
            'name': customer.name,
            'code': customer.customer_code,
            'balance': str(customer.adjusted_outstanding_balance()),
        })
    except Customer.DoesNotExist:
        return JsonResponse({'success': False})
        

@login_required
def sale_order_create(request):
    if request.method == 'POST':
        try:
            customer_id = request.POST.get('customer')
            warehouse_id = request.POST.get('warehouse')
            status = request.POST.get('status', 'pending')
            delivery_date = request.POST.get('delivery_date', '')
            customer_po = request.POST.get('customer_po', '')
            notes = request.POST.get('notes', '')
            advance = request.POST.get('advance', 0)
            discount = request.POST.get('discount', 0)
            
            if not customer_id or not warehouse_id:
                messages.error(request, 'Customer and Warehouse required!')
                return redirect('sale_order_create')
            
            product_ids = request.POST.getlist('product_id[]')
            if not product_ids or not any(product_ids):
                messages.error(request, 'Add at least one product!')
                return redirect('sale_order_create')
            
            order = SaleOrder.objects.create(
                customer_id=customer_id,
                warehouse_id=warehouse_id,
                status=status,
                delivery_date=delivery_date if delivery_date else None,
                customer_po_number=customer_po,
                notes=notes,
                advance_payment=Decimal(advance),
                discount_value=Decimal(discount),
                created_by=request.user
            )
            
            qtys = request.POST.getlist('qty[]')
            prices = request.POST.getlist('price[]')
            
            for i in range(len(product_ids)):
                if product_ids[i]:
                    SaleOrderItem.objects.create(
                        order=order,
                        product_id=product_ids[i],
                        qty=float(qtys[i]),
                        price=Decimal(prices[i])
                    )
            
            messages.success(request, f'Order #{order.order_no} created!')
            return redirect('sale_order_list')
            
        except Exception as e:
            messages.error(request, f'Error: {str(e)}')
            return redirect('sale_order_create')
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'customers': Customer.objects.all().order_by('customer_code'),
        'warehouses': Warehouse.objects.all(),
        'products': Product.objects.all().order_by('name')[:50],
    }
    return render(request, 'orders/sale_order_create.html', context)
    
    
@login_required
def sale_order_detail(request, pk):
    """Sale Order Detail View"""
    order = get_object_or_404(
        SaleOrder.objects.select_related('customer', 'warehouse')
        .prefetch_related('items', 'items__product', 'challans'), 
        pk=pk
    )
    
    # Calculate delivery stats for each item
    items = order.items.all()
    total_ordered = sum(item.qty for item in items)
    total_delivered = sum(order.delivered_qty(item.product) for item in items)
    total_pending = total_ordered - total_delivered  # Calculate in view, not template
    delivery_percent = round((total_delivered / total_ordered) * 100) if total_ordered > 0 else 0
    
    # Add delivered qty to each item
    for item in items:
        item.delivered = order.delivered_qty(item.product)
        item.pending = item.qty - item.delivered
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'order': order,
        'items': items,
        'challans': order.challans.all(),
        'total_ordered': total_ordered,
        'total_delivered': total_delivered,
        'total_pending': total_pending,  # Pre-calculated
        'delivery_percent': delivery_percent,
    }
    return render(request, 'orders/sale_order_detail.html', context)
    
    
    
@login_required
def sale_order_update(request, pk):
    """Update Sale Order"""
    order = get_object_or_404(
        SaleOrder.objects.select_related('customer', 'warehouse')
        .prefetch_related('items', 'items__product'), 
        pk=pk
    )
    
    if request.method == 'POST':
        try:
            order.customer_id = request.POST.get('customer')
            order.warehouse_id = request.POST.get('warehouse')
            order.status = request.POST.get('status', 'pending')
            order.delivery_date = request.POST.get('delivery_date') or None
            order.customer_po_number = request.POST.get('customer_po', '')
            order.notes = request.POST.get('notes', '')
            order.advance_payment = Decimal(request.POST.get('advance', 0))
            order.discount_value = Decimal(request.POST.get('discount', 0))
            order.save()
            
            # Delete old items and recreate
            order.items.all().delete()
            
            product_ids = request.POST.getlist('product_id[]')
            qtys = request.POST.getlist('qty[]')
            prices = request.POST.getlist('price[]')
            
            for i in range(len(product_ids)):
                if product_ids[i]:
                    SaleOrderItem.objects.create(
                        order=order,
                        product_id=product_ids[i],
                        qty=float(qtys[i]),
                        price=Decimal(prices[i])
                    )
            
            messages.success(request, f'Order #{order.order_no} updated!')
            return redirect('sale_order_detail', pk=order.pk)
            
        except Exception as e:
            messages.error(request, f'Error: {str(e)}')
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'order': order,
        'customers': Customer.objects.all().order_by('customer_code'),
        'warehouses': Warehouse.objects.all(),
        'products': Product.objects.all().order_by('name')[:50],
    }
    return render(request, 'orders/sale_order_update.html', context)
    
    
@login_required
def sale_order_quick_status(request, pk, status):
    """Quick status update"""
    order = get_object_or_404(SaleOrder, pk=pk)
    valid_statuses = ['pending', 'confirmed', 'processing', 'ready', 'partially_delivered', 'delivered', 'invoiced', 'cancelled']
    
    if status in valid_statuses:
        order.status = status
        order.save()
        messages.success(request, f'✅ Order #{order.order_no} → {order.get_status_display()}')
    else:
        messages.error(request, 'Invalid status!')
    
    return redirect('sale_order_list')


@login_required
def sale_order_create_challan(request, pk):
    """Create Delivery Challan from Sale Order"""
    order = get_object_or_404(SaleOrder, pk=pk)
    
    if order.status not in ['confirmed', 'processing', 'ready', 'partially_delivered']:
        messages.error(request, '❌ Order must be Confirmed or Processing to create challan!')
        return redirect('sale_order_detail', pk=order.pk)
    
    try:
        with transaction.atomic():
            challan = DeliveryChallan.objects.create(
                order=order,
                customer=order.customer,
                warehouse=order.warehouse,
                reason='sale',
                created_by=request.user
            )
            
            for item in order.items.all():
                already_delivered = DeliveryChallanItem.objects.filter(
                    challan__order=order,
                    product=item.product
                ).aggregate(total=Sum('qty'))['total'] or 0
                
                pending = item.qty - already_delivered
                
                if pending > 0:
                    DeliveryChallanItem.objects.create(
                        challan=challan,
                        product=item.product,
                        order_qty=item.qty,
                        qty=pending,
                        price=item.price
                    )
            
            order.update_delivery_status()
            messages.success(request, f'✅ Challan #{challan.challan_no} created! Order status: {order.get_status_display()}')
            
    except Exception as e:
        messages.error(request, f'❌ Error: {str(e)}')
    
    return redirect('sale_order_detail', pk=order.pk)


# ============================================
# DATABASE BACKUP & RCLONE CLOUD MANAGEMENT CONFIGURATIONS
# ============================================
import json
import os
import subprocess
import shutil
import time
import re
from django.contrib.auth.decorators import login_required
from django.contrib import messages
from django.shortcuts import render, redirect, get_object_or_404
from django.utils.timezone import now
from .models import (
    SaleOrder, Sale, SaleItem, Product, Unit, Category, 
    Brand, Location, Types, CompanyInfo
)

# Configurations (Termux paths and Rclone settings)
BACKUP_DIR = "/storage/emulated/0/Download/Backups"
REMOTE_NAME = "gdrive"
REMOTE_DIR = "TermuxBackups"


def run_rclone_cmd(cmd):
    """Utility to execute shell commands securely."""
    result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    return result.returncode == 0, result.stderr


def get_remote_backups():
    """Fetches live remote files from Google Drive using lsjson, sorted newest first."""
    cmd = ["rclone", "lsjson", f"{REMOTE_NAME}:{REMOTE_DIR}"]
    result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if result.returncode == 0 and result.stdout:
        try:
            files_data = json.loads(result.stdout)
            # Filter directories, keep only real files
            files_only = [f for f in files_data if not f.get("IsDir")]
            # Sort chronologically (Newest first)
            files_only.sort(key=lambda x: x.get("ModTime", ""), reverse=True)
            return files_only
        except Exception:
            return []
    return []


@login_required
def database_backup_view(request):
    """
    Handles local backup generation, rclone cloud uploads, 
    rolling 3-file retention, and interactive database restoration.
    """
    restore_file = request.GET.get("restore")
    delete_file = request.GET.get("delete")

    # ---- 1. CLOUD RESTORE LOGIC ----
    if restore_file:
        os.makedirs(BACKUP_DIR, exist_ok=True)
        local_path = os.path.join(BACKUP_DIR, restore_file)

        # Download the file from Google Drive to local Backups folder
        success, err = run_rclone_cmd([
            "rclone", "copyto", 
            f"{REMOTE_NAME}:{REMOTE_DIR}/{restore_file}", 
            local_path
        ])

        if success:
            # Check if it's an SQLite backup and replace current database file
            if restore_file.endswith(".sqlite3") and os.path.exists(local_path):
                try:
                    shutil.copy(local_path, "db.sqlite3")
                    messages.success(request, f"🎉 '{restore_file}' successfully downloaded and database restored!")
                except Exception as db_err:
                    messages.error(request, f"❌ Local replacement failed: {db_err}")
            else:
                messages.success(request, f"📥 File '{restore_file}' downloaded safely to {BACKUP_DIR}.")
        else:
            messages.error(request, f"❌ Cloud restore download failed: {err}")
        return redirect("database_backup")

    # ---- 2. CLOUD DELETE LOGIC ----
    if delete_file:
        success, err = run_rclone_cmd([
            "rclone", "deletefile", 
            f"{REMOTE_NAME}:{REMOTE_DIR}/{delete_file}"
        ])
        if success:
            messages.success(request, f"🗑️ '{delete_file}' deleted permanently from Google Drive.")
        else:
            messages.error(request, f"❌ Cloud delete failed: {err}")
        return redirect("database_backup")

    # ---- 3. CREATE BACKUP AND SYNC LOGIC (POST) ----
    if request.method == "POST":
        action = request.POST.get("action")
        os.makedirs(BACKUP_DIR, exist_ok=True)
        
        timestamp = int(time.time())
        filename = ""

        if action == "json_backup":
            filename = f"backup_full_{timestamp}.json"
            local_path = os.path.join(BACKUP_DIR, filename)
            # Execute Django standard dumpdata
            subprocess.run(f"python manage.py dumpdata > {local_path}", shell=True)

        elif action == "sqlite_backup":
            filename = f"backup_{timestamp}.sqlite3"
            local_path = os.path.join(BACKUP_DIR, filename)
            # Direct binary copy of db.sqlite3
            if os.path.exists("db.sqlite3"):
                shutil.copy("db.sqlite3", local_path)
            else:
                messages.error(request, "❌ Central db.sqlite3 file not found.")
                return redirect("database_backup")

        # Sync/Copy the updated local backups folder to Google Drive
        success, err = run_rclone_cmd(["rclone", "copy", BACKUP_DIR, f"{REMOTE_NAME}:{REMOTE_DIR}"])

        if success:
            # Active 3-files maximum retention enforcement rules
            remote_files = get_remote_backups()
            if len(remote_files) > 3:
                # Target files older than the top 3 index
                for old_file in remote_files[3:]:
                    old_name = old_file["Name"]
                    run_rclone_cmd(["rclone", "deletefile", f"{REMOTE_NAME}:{REMOTE_DIR}/{old_name}"])

            messages.success(request, f"🚀 Backup '{filename}' created and safely synced to Google Drive!")
        else:
            messages.error(request, f"❌ Cloud backup sync failed: {err}")

        return redirect("database_backup")

    # ---- 4. RENDER DATA PROCESSING ----
    cloud_files = get_remote_backups()
    
    backup_files = [f["Name"] for f in cloud_files]
    file_sizes = {f["Name"]: f"{round(f['Size'] / 1024, 2)} KB" for f in cloud_files}
    file_dates = {f["Name"]: f["ModTime"][:19].replace("T", " ") for f in cloud_files}

    # Better & Secure Way: Ask rclone directly about configuration details
    rclone_email = None
    try:
        # Runs 'rclone config show gdrive' to get live configuration parameters securely
        res = subprocess.run(["rclone", "config", "show", REMOTE_NAME], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        if res.returncode == 0 and res.stdout:
            # Scan output for any linked email address
            email_match = re.search(r'[\w\.-]+@[\w\.-]+\.\w+', res.stdout)
            if email_match:
                rclone_email = email_match.group(0)
    except Exception:
        pass

    # Fallback Option: If rclone command didn't output direct email, read config safely
    if not rclone_email:
        rclone_conf_path = '/data/data/com.termux/files/home/.config/rclone/rclone.conf'
        if os.path.exists(rclone_conf_path):
            try:
                with open(rclone_conf_path, 'r') as f:
                    content = f.read()
                    email_match = re.search(r'[\w\.-]+@[\w\.-]+\.\w+', content)
                    if email_match:
                        rclone_email = email_match.group(0)
            except Exception:
                pass

    context = {
        "backup_dir": f"{REMOTE_NAME}:{REMOTE_DIR} (Cloud)",
        "backup_files": backup_files,
        "file_sizes": file_sizes,
        "file_dates": file_dates,
        "rclone_email": rclone_email,
    }
    return render(request, "database_backup.html", context)



@login_required
def sale_order_convert_invoice(request, pk):
    """Convert Sale Order to Sale/Invoice"""
    from django.db import transaction as db_transaction
    
    order = get_object_or_404(SaleOrder, pk=pk)
    
    if order.status not in ['delivered', 'partially_delivered', 'ready']:
        messages.error(request, '❌ Order must be Delivered to convert to invoice!')
        return redirect('sale_order_detail', pk=order.pk)
    
    if order.converted_to_sale:
        messages.error(request, '❌ Order already converted to invoice!')
        return redirect('sale_order_detail', pk=order.pk)
    
    try:
        with db_transaction.atomic():
            sale = Sale.objects.create(
                warehouse=order.warehouse,
                customer=order.customer,
                bill_no=f"INV-{order.order_no}",
                sale_date=now(),
                paid=order.advance_payment,
                discount_value=order.discount_value,
                created_by=request.user
            )
            
            for item in order.items.all():
                SaleItem.objects.create(
                    sale=sale,
                    product=item.product,
                    qty=item.qty,
                    price=item.price
                )
            
            order.status = 'invoiced'
            order.converted_to_sale = sale
            order.save()
            
            messages.success(request, f'✅ Order converted to Invoice #{sale.bill_no}!')
            return redirect('sale_detail', pk=sale.pk)
            
    except Exception as e:
        messages.error(request, f'❌ Error: {str(e)}')
        return redirect('sale_order_detail', pk=order.pk)
        

