@login_required
def loan_create(request):
    """Create new loan request"""
    
    if request.method == 'POST':
        try:
            # Validation
            if not hasattr(request.user, 'shareholder_profile'):
                messages.error(request, 'Only shareholders can apply for loans!')
                return redirect('dashboard')
            
            shareholder = request.user.shareholder_profile
            principal = Decimal(request.POST.get('principal', 0))
            
            if principal <= 0:
                messages.error(request, 'Principal must be greater than zero!')
                return redirect('loan_create')
            
            # Check collateral
            shares = shareholder.shares.filter(is_locked=False, quantity__gt=0)
            total_value = sum(share.total_value() for share in shares)
            
            loan_amount = principal * (Decimal(request.POST.get('ltv_ratio', 60)) / 100)
            if loan_amount > total_value:
                messages.error(request, f'Insufficient collateral! Required: Rs. {loan_amount:,.2f}')
                return redirect('loan_create')
            
            loan = ShareholderLoan.objects.create(
                loan_type=request.POST.get('loan_type'),
                shareholder=shareholder,
                principal=principal,
                interest_rate=Decimal(request.POST.get('interest_rate', 12)),
                start_date=request.POST.get('start_date'),
                maturity_date=request.POST.get('maturity_date'),
                ltv_ratio=Decimal(request.POST.get('ltv_ratio', 60)),
                processing_fee=Decimal(request.POST.get('processing_fee', 0)),
                status='draft',
                created_by=request.user,
                notes=request.POST.get('notes', '')
            )
            
            # Add collateral shares
            share_ids = request.POST.getlist('collateral_shares[]')
            if share_ids:
                for share_id in share_ids:
                    share = Share.objects.get(id=share_id, shareholder=shareholder)
                    loan.collateral_shares.add(share)
                loan.collateral_value = sum(
                    share.total_value() for share in loan.collateral_shares.all()
                )
                loan.save()
            
            messages.success(request, f'✅ Loan #{loan.loan_no} created! Waiting for approval.')
            return redirect('loan_detail', pk=loan.pk)
            
        except Exception as e:
            messages.error(request, f'❌ Error: {str(e)}')
    
    shareholder = request.user.shareholder_profile if hasattr(request.user, 'shareholder_profile') else None
    shares = shareholder.shares.filter(is_locked=False, quantity__gt=0) if shareholder else []
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'loan_types': ShareholderLoan.LOAN_TYPES,
        'shares': shares,
        'shareholder': shareholder,
    }
    return render(request, 'shareholders/loan/create.html', context)


@login_required
def loan_detail(request, pk):
    """Loan detail view"""
    
    loan = get_object_or_404(ShareholderLoan, pk=pk)
    
    # Check permission
    if not request.user.is_superuser and not request.user.is_staff:
        if not hasattr(request.user, 'shareholder_profile'):
            messages.error(request, 'Access denied!')
            return redirect('dashboard')
        if loan.shareholder != request.user.shareholder_profile:
            messages.error(request, 'Access denied!')
            return redirect('dashboard')
    
    # Calculate interest
    loan.accrue_interest()
    
    # Get payments
    interest_payments = InterestPayment.objects.filter(loan=loan)
    principal_payments = PrincipalPayment.objects.filter(loan=loan)
    
    # Calculate total paid
    total_interest_paid = interest_payments.aggregate(total=Sum('amount'))['total'] or 0
    total_principal_paid = principal_payments.aggregate(total=Sum('amount'))['total'] or 0
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'loan': loan,
        'interest_payments': interest_payments,
        'principal_payments': principal_payments,
        'total_interest_paid': total_interest_paid,
        'total_principal_paid': total_principal_paid,
        'remaining_balance': loan.outstanding + loan.interest_accrued,
        'is_admin': request.user.is_superuser or request.user.is_staff,
    }
    return render(request, 'shareholders/loan/detail.html', context)


@login_required
def loan_pay(request, pk):
    """Make loan payment"""
    
    loan = get_object_or_404(ShareholderLoan, pk=pk)
    
    # Check permission
    if not request.user.is_superuser and not request.user.is_staff:
        if not hasattr(request.user, 'shareholder_profile'):
            messages.error(request, 'Access denied!')
            return redirect('dashboard')
        if loan.shareholder != request.user.shareholder_profile:
            messages.error(request, 'Access denied!')
            return redirect('dashboard')
    
    if request.method == 'POST':
        try:
            amount = Decimal(request.POST.get('amount', 0))
            
            if amount <= 0:
                messages.error(request, 'Amount must be greater than zero!')
                return redirect('loan_pay', pk=pk)
            
            # Check if amount exceeds total due
            total_due = loan.outstanding + loan.interest_accrued
            if amount > total_due:
                messages.error(request, f'Amount cannot exceed total due: Rs. {total_due:,.2f}')
                return redirect('loan_pay', pk=pk)
            
            # Accrue interest first
            loan.accrue_interest()
            
            # Make payment
            loan.make_payment(
                amount=amount,
                payment_method=request.POST.get('payment_method', 'Cash'),
                reference_no=request.POST.get('reference_no', '')
            )
            
            # Update loan status
            if loan.outstanding <= 0 and loan.interest_accrued <= 0:
                loan.status = 'paid'
                loan.save()
            
            messages.success(request, f'✅ Payment of Rs. {amount:,.2f} made successfully!')
            return redirect('loan_detail', pk=loan.pk)
            
        except Exception as e:
            messages.error(request, f'❌ Error: {str(e)}')
    
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'loan': loan,
        'total_due': loan.outstanding + loan.interest_accrued,
    }
    return render(request, 'shareholders/loan/pay.html', context)


@login_required
def loan_statement(request, pk):
    """Generate loan statement PDF"""
    
    loan = get_object_or_404(ShareholderLoan, pk=pk)
    
    from reportlab.lib.pagesizes import A4
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
    from reportlab.lib import colors
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.units import inch
    from reportlab.lib.enums import TA_CENTER, TA_RIGHT
    
    buffer = BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, topMargin=0.5*inch, bottomMargin=0.5*inch)
    styles = getSampleStyleSheet()
    story = []
    
    company = CompanyInfo.objects.first()
    company_name = company.name if company else "ERP SYSTEM"
    
    # Title
    title_style = ParagraphStyle('Title', parent=styles['Heading1'], fontSize=18, alignment=TA_CENTER)
    story.append(Paragraph(company_name, title_style))
    story.append(Paragraph("LOAN STATEMENT", title_style))
    story.append(Paragraph(f"Loan No: {loan.loan_no}", styles['Normal']))
    story.append(Spacer(1, 0.3*inch))
    
    # Loan Info
    info_data = [
        ['Shareholder:', loan.shareholder.name],
        ['Loan Type:', loan.get_loan_type_display()],
        ['Principal:', f"Rs. {loan.principal:,.2f}"],
        ['Interest Rate:', f"{loan.interest_rate}%"],
        ['Start Date:', loan.start_date.strftime('%d-%m-%Y')],
        ['Maturity Date:', loan.maturity_date.strftime('%d-%m-%Y')],
        ['Status:', loan.get_status_display()],
    ]
    
    info_table = Table(info_data, colWidths=[2*inch, 4*inch])
    info_table.setStyle(TableStyle([
        ('VALIGN', (0, 0), (-1, -1), 'TOP'),
        ('TOPPADDING', (0, 0), (-1, -1), 4),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
    ]))
    story.append(info_table)
    story.append(Spacer(1, 0.3*inch))
    
    # Payment Summary
    interest_payments = InterestPayment.objects.filter(loan=loan)
    principal_payments = PrincipalPayment.objects.filter(loan=loan)
    
    payment_data = [
        ['Description', 'Amount (Rs.)'],
        ['Total Principal', f"{loan.principal:,.2f}"],
        ['Principal Paid', f"{loan.principal - loan.outstanding:,.2f}"],
        ['Principal Outstanding', f"{loan.outstanding:,.2f}"],
        ['', ''],
        ['Interest Accrued', f"{loan.interest_accrued:,.2f}"],
        ['Interest Paid', f"{loan.interest_paid:,.2f}"],
        ['Total Due', f"{loan.outstanding + loan.interest_accrued:,.2f}"],
    ]
    
    payment_table = Table(payment_data, colWidths=[3*inch, 2*inch])
    payment_table.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#1a1d2e')),
        ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('GRID', (0, 0), (-1, -1), 0.5, colors.grey),
        ('ALIGN', (1, 1), (1, -1), 'RIGHT'),
        ('BACKGROUND', (0, -1), (-1, -1), colors.HexColor('#e8ecf4')),
        ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
    ]))
    story.append(payment_table)
    story.append(Spacer(1, 0.3*inch))
    
    # Payment History
    if interest_payments or principal_payments:
        story.append(Paragraph("<b>Payment History</b>", styles['Heading2']))
        history_data = [['Date', 'Type', 'Amount', 'Method']]
        
        for payment in interest_payments:
            history_data.append([
                payment.payment_date.strftime('%d-%m-%Y'),
                'Interest',
                f"Rs. {payment.amount:,.2f}",
                payment.payment_method or '-'
            ])
        
        for payment in principal_payments:
            history_data.append([
                payment.payment_date.strftime('%d-%m-%Y'),
                'Principal',
                f"Rs. {payment.amount:,.2f}",
                payment.payment_method or '-'
            ])
        
        history_table = Table(history_data, repeatRows=1)
        history_table.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#1a1d2e')),
            ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
            ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
            ('GRID', (0, 0), (-1, -1), 0.5, colors.grey),
        ]))
        story.append(history_table)
    
    doc.build(story)
    buffer.seek(0)
    
    response = HttpResponse(buffer, content_type='application/pdf')
    response['Content-Disposition'] = f'attachment; filename="Loan_Statement_{loan.loan_no}.pdf"'
    return response
    
