def restore_database(file_path, filename):
    """Restore database from backup file"""
    import shutil
    
    try:
        db_path = settings.BASE_DIR / 'db.sqlite3'
        
        # Check if file is compressed
        if filename.endswith('.gz'):
            import gzip
            temp_file = file_path.replace('.gz', '')
            with gzip.open(file_path, 'rb') as f_in:
                with open(temp_file, 'wb') as f_out:
                    f_out.write(f_in.read())
            file_path = temp_file
        
        # Backup current database before restore (safety)
        safety_backup = settings.BASE_DIR / f'db_backup_before_restore_{datetime.now().strftime("%Y%m%d_%H%M%S")}.sqlite3'
        shutil.copy2(db_path, safety_backup)
        
        # Restore
        shutil.copy2(file_path, db_path)
        
        # Clean temp file
        if file_path != os.path.join(settings.BACKUP_DIR, filename):
            try:
                os.remove(file_path)
            except:
                pass
        
        return JsonResponse({
            'success': True,
            'message': f'✅ Database restored from {filename}',
            'safety_backup': str(safety_backup)
        })
        
    except Exception as e:
        return JsonResponse({'success': False, 'message': str(e)})

def get_cloud_files(request):
    """Get list of backup files from Google Drive"""
    try:
        if not settings.RCLONE_ENABLED:
            return JsonResponse({
                'success': False,
                'message': 'Cloud upload is disabled in settings!'
            })
        
        cmd = ["rclone", "lsjson", f"{settings.RCLONE_REMOTE_NAME}:{settings.RCLONE_REMOTE_DIR}"]
        result = subprocess.run(cmd, capture_output=True, text=True)
        
        if result.returncode != 0:
            return JsonResponse({'success': False, 'files': []})
        
        files_data = json.loads(result.stdout)
        files = []
        
        for f in files_data:
            if not f.get('IsDir', False):
                name = f.get('Name', '')
                if name.endswith('.sqlite3.gz') or name.endswith('.sqlite3'):
                    files.append({
                        'name': name,
                        'size': f.get('Size', 0),
                        'size_display': f"{f.get('Size', 0) / (1024*1024):.1f} MB",
                        'modified': f.get('ModTime', '')[:19].replace('T', ' ')
                    })
        
        files.sort(key=lambda x: x['modified'], reverse=True)
        
        return JsonResponse({
            'success': True,
            'files': files
        })
        
    except Exception as e:
        return JsonResponse({'success': False, 'message': str(e)})
        
@login_required
def upload_backup_file(request):
    """
    Internal storage se backup file select karke local backup folder mein add karein
    """
    if not request.user.is_superuser:
        messages.error(request, 'Access denied! Only superuser can upload backup files.')
        return redirect('database_backup')
    
    if request.method == 'POST' and request.FILES.get('backup_file'):
        try:
            uploaded_file = request.FILES['backup_file']
            filename = uploaded_file.name
            
            allowed_extensions = ['.sqlite3', '.sqlite3.gz', '.gz', '.json']
            is_allowed = any(filename.endswith(ext) for ext in allowed_extensions)
            
            if not is_allowed:
                messages.error(request, f'❌ Invalid file type! Allowed: {", ".join(allowed_extensions)}')
                return redirect('database_backup')
            
            if uploaded_file.size > 500 * 1024 * 1024:
                messages.error(request, '❌ File too large! Maximum size: 500MB')
                return redirect('database_backup')
            
            backup_dir = settings.BACKUP_DIR
            os.makedirs(backup_dir, exist_ok=True)
            
            file_path = os.path.join(backup_dir, filename)
            if os.path.exists(file_path):
                name, ext = os.path.splitext(filename)
                timestamp = datetime.now().strftime('_%Y%m%d_%H%M%S')
                new_filename = f"{name}{timestamp}{ext}"
                file_path = os.path.join(backup_dir, new_filename)
            else:
                new_filename = filename
            
            with open(file_path, 'wb+') as destination:
                for chunk in uploaded_file.chunks():
                    destination.write(chunk)
            
            size_mb = uploaded_file.size / (1024 * 1024)
            
            messages.success(
                request, 
                f'✅ File "{new_filename}" uploaded successfully! Size: {size_mb:.1f} MB'
            )
            
        except Exception as e:
            messages.error(request, f'❌ Error uploading file: {str(e)}')
        
        return redirect('database_backup')
    
    # ✅ YEH ADD KARO - GET request par upload form show karein
    context = {
        'company_name': CompanyInfo.objects.first().name if CompanyInfo.objects.exists() else 'ERP System',
        'allowed_extensions': ['.sqlite3', '.sqlite3.gz', '.gz', '.json'],
        'max_size_mb': 500,
    }
    return render(request, 'database_backup_upload.html', context)
    
@login_required
def vendor_delete(request, pk):
    """Delete a vendor with confirmation"""
    vendor = get_object_or_404(Vendor, pk=pk)
    
    # Check permission - only superuser or staff can delete
    if not request.user.is_superuser and not request.user.is_staff:
        messages.error(request, '❌ Access denied! Only administrators can delete vendors.')
        return redirect('vendor_list')
    
    # Check if vendor has any purchases
    if vendor.purchase_set.exists():
        messages.error(
            request, 
            f'❌ Cannot delete "{vendor.name}" because they have {vendor.purchase_set.count()} purchase(s) associated with them!'
        )
        return redirect('vendor_list')
    
    if request.method == 'POST':
        vendor_name = vendor.name
        vendor.delete()
        messages.success(request, f'🗑️ Vendor "{vendor_name}" deleted successfully!')
        return redirect('vendor_list')
    
    return redirect('vendor_list')
    
        
# views_frontend.py - Update the search_products_ajax function

@login_required
def search_products_ajax(request):
    """
    AJAX: Live product search for SALE with batch information
    - Shows selling price from latest batch
    - Shows stock
    - Shows batch count and latest batch price
    - Shows batch remaining quantity
    - Warning if no selling price set
    """
    query = request.GET.get('q', '').strip()
    warehouse_id = request.GET.get('warehouse_id', '')
    
    if len(query) < 1:
        return JsonResponse({'success': True, 'products': []})
    
    products = Product.objects.filter(
        Q(name__icontains=query) |
        Q(serial_no__icontains=query) |
        Q(barcode__icontains=query)
    ).distinct()[:15]
    
    result = []
    for product in products:
        stock = 0
        price = 0
        selling_price = 0
        has_selling_price = False
        warning_message = ''
        batch_count = 0
        latest_batch_price = 0
        batch_remaining_qty = 0  # ✅ NEW: Batch remaining quantity
        batch_id = None  # ✅ NEW: Batch ID
        
        if warehouse_id:
            inventory = Inventory.objects.filter(product=product, warehouse_id=warehouse_id).first()
            stock = inventory.stock if inventory else 0
            
            # ✅ Get all batches with remaining stock
            batches = StockBatch.objects.filter(
                product=product,
                warehouse_id=warehouse_id,
                remaining_qty__gt=0
            ).order_by('id')
            
            batch_count = batches.count()
            
            # ✅ Get latest batch (most recent)
            latest_batch = batches.first()
            
            if latest_batch:
                latest_batch_price = float(latest_batch.price)
                selling_price = float(latest_batch.selling_price) if latest_batch.selling_price > 0 else 0
                has_selling_price = selling_price > 0
                batch_remaining_qty = float(latest_batch.remaining_qty)  # ✅ NEW
                batch_id = latest_batch.id  # ✅ NEW
                
                if not has_selling_price and stock > 0:
                    warning_message = '⚠️ No selling price set for this batch!'
            else:
                price = float(product.price)
                warning_message = '⚠️ No stock batch found with selling price!'
        else:
            price = float(product.price)
            # Check any warehouse
            any_batch = StockBatch.objects.filter(
                product=product,
                remaining_qty__gt=0
            ).order_by('id').first()
            
            if any_batch:
                batch_count = StockBatch.objects.filter(
                    product=product,
                    remaining_qty__gt=0
                ).count()
                latest_batch_price = float(any_batch.price)
                selling_price = float(any_batch.selling_price) if any_batch.selling_price > 0 else 0
                has_selling_price = selling_price > 0
                batch_remaining_qty = float(any_batch.remaining_qty)  # ✅ NEW
                batch_id = any_batch.id  # ✅ NEW
            else:
                warning_message = '⚠️ Select a warehouse to check selling price!'
        
        display_price = selling_price if has_selling_price else 0
        
        result.append({
            'id': product.id,
            'name': product.name,
            'barcode': product.barcode or '',
            'serial_no': product.serial_no or '',
            'price': str(display_price),  # Selling price (0 if not set)
            'cost_price': str(latest_batch_price if latest_batch_price > 0 else price),
            'stock': stock,
            'unit': product.unit.name if product.unit else '',
            'has_selling_price': has_selling_price,
            'warning': warning_message,
            'selling_price': str(selling_price) if has_selling_price else '0',
            'batch_count': batch_count,
            'latest_batch_price': str(latest_batch_price) if latest_batch_price > 0 else '0',
            'batch_remaining_qty': str(batch_remaining_qty),  # ✅ NEW
            'batch_id': batch_id,  # ✅ NEW
        })
    
    return JsonResponse({'success': True, 'products': result})
    
